import Foundation
import AcpiraModels

// The synthetic session views generated by lab/ios-fixtures.gen.ts. The web reference page renders the same files,
// so a simulator screenshot of a fixture and a LAB screenshot of it compare like for like.
public enum Fixtures {
  /// Fixture names that hold a SessionView. The cards' fixtures after `empty` are hand-written (plan approval, notice
  /// rows, records, failure cards, session states, subagents, the built-in agent's controls with a sidekick); `records`
  /// carries one deliberately unknown block type
  public static let sessionNames = ["showcase", "running", "streaming", "question", "queued", "stopped", "empty", "diagrams", "media",
                                    "plan", "notices", "records", "context", "failure", "login", "readonly", "closed",
                                    "error", "connecting", "chatgpt", "goal", "subagents", "builtin"]

  /// Raw JSON of `synthetic/<name>.json`
  public static func data(_ name: String) -> Data? {
    guard let url = Bundle.module.url(forResource: name, withExtension: "json", subdirectory: "synthetic") else { return nil }
    return try? Data(contentsOf: url)
  }

  /// A stored file of the fixture sessions (`synthetic/blobs/<name>`), what the engine's blob store holds for a real one
  public static func blob(_ name: String) -> Data? {
    guard let url = Bundle.module.url(forResource: name, withExtension: nil, subdirectory: "synthetic/blobs") else { return nil }
    return try? Data(contentsOf: url)
  }

  public static func decode<T: Decodable>(_ type: T.Type, _ name: String) throws -> T {
    guard let data = data(name) else { throw CocoaError(.fileNoSuchFile) }
    return try JSONDecoder().decode(type, from: data)
  }

  public static func session(_ name: String) -> SessionView? { try? decode(SessionView.self, name) }

  /// The child transcripts a fixture's subagents show once observed (`synthetic/<name>.children.json`, keyed by
  /// subagent id): what the engine's `subagent` pushes would carry. Empty for a fixture without children
  public static func subagentTranscripts(_ name: String) -> [String: SubagentTranscript] {
    (try? decode([String: SubagentTranscript].self, "\(name).children")) ?? [:]
  }
  public static var agents: [AgentInfo] { (try? decode([AgentInfo].self, "agents")) ?? [] }
  public static var sessions: [SessionSummary] { (try? decode([SessionSummary].self, "sessions")) ?? [] }
  public static var accounts: [AccountInfo] { (try? decode([AccountInfo].self, "accounts")) ?? [] }

  /// The fixtures' clock: quota resets and timestamps are written relative to it, so the app reads it in place of the
  /// real time while it shows fixtures
  public static var now: Date {
    struct Clock: Decodable { var now: String }
    let iso = (try? decode(Clock.self, "clock"))?.now ?? ""
    return Date(iso: iso) ?? Date()
  }
}
